const ShuffleHero = () => {
  return (
    <section className="w-full px-8 py-12 grid grid-cols-1 md:grid-cols-2 items-center gap-8 max-w-6xl mx-auto">
      <div>
        <span className="block mb-4 md:text-sm  text-sm font-bold tracking-wider text-orange-600 uppercase">
          Better every day
        </span>
        <h3 className="text-4xl md:text-6xl font-semibold">
          Let&apos;s change it up a bit
        </h3>
        <p className="text-base md:text-lg text-muted-foreground my-4 md:my-6">
          From sunrise yoga to late-night spin, book a spot at studios near you
          in seconds. New classes drop every Monday.
        </p>
        <button className="bg-orange-500 text-white font-medium py-2 px-4 rounded transition-all hover:bg-orange-600 active:scale-95">
          Find a class
        </button>
      </div>
      <ShuffleGrid />
    </section>
  );
};

type Square = { id: number; src: string };

const shuffle = (array: Square[]) => {
  let currentIndex = array.length,
    randomIndex: number;

  while (currentIndex !== 0) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;

    [array[currentIndex], array[randomIndex]] = [
      array[randomIndex],
      array[currentIndex],
    ];
  }

  return array;
};

